/**
 * Cross-Platform Fullscreen Utility
 * Supports Standard Fullscreen API, WebKit/Safari prefixes, and iOS Mobile Pseudo-Fullscreen fallback.
 */

export function isFullscreen(): boolean {
  if (typeof document === 'undefined') return false;
  const doc = document as any;
  return !!(
    doc.fullscreenElement ||
    doc.webkitFullscreenElement ||
    doc.mozFullScreenElement ||
    doc.msFullscreenElement ||
    document.body.classList.contains('is-pseudo-fullscreen')
  );
}

export async function toggleFullscreen(targetElement: HTMLElement = document.documentElement): Promise<boolean> {
  if (typeof document === 'undefined') return false;
  const doc = document as any;
  const el = targetElement as any;

  if (isFullscreen()) {
    // 1. Exit Pseudo-Fullscreen if active
    if (document.body.classList.contains('is-pseudo-fullscreen')) {
      document.body.classList.remove('is-pseudo-fullscreen');
      window.dispatchEvent(new Event('fullscreenchange'));
      window.dispatchEvent(new Event('resize'));
      return false;
    }

    // 2. Exit Native Fullscreen
    try {
      if (document.exitFullscreen) {
        await document.exitFullscreen();
      } else if (doc.webkitExitFullscreen) {
        doc.webkitExitFullscreen();
      } else if (doc.mozCancelFullScreen) {
        doc.mozCancelFullScreen();
      } else if (doc.msExitFullscreen) {
        doc.msExitFullscreen();
      }
    } catch {
      // Ignored if browser rejects
    }
    window.dispatchEvent(new Event('resize'));
    return false;
  } else {
    // 1. Try Native Fullscreen
    let requested = false;
    try {
      if (el.requestFullscreen) {
        await el.requestFullscreen({ navigationUI: 'hide' });
        requested = true;
      } else if (el.webkitRequestFullscreen) {
        el.webkitRequestFullscreen();
        requested = true;
      } else if (el.mozRequestFullScreen) {
        el.mozRequestFullScreen();
        requested = true;
      } else if (el.msRequestFullscreen) {
        el.msRequestFullscreen();
        requested = true;
      }
    } catch {
      requested = false;
    }

    // 2. Fallback to Pseudo-Fullscreen (e.g. iPhone Safari which doesn't support element fullscreen)
    if (!requested) {
      document.body.classList.add('is-pseudo-fullscreen');
      window.scrollTo(0, 0);
      window.dispatchEvent(new Event('fullscreenchange'));
      window.dispatchEvent(new Event('resize'));
    }

    return true;
  }
}

export function onFullscreenChange(callback: (active: boolean) => void): () => void {
  if (typeof document === 'undefined') return () => {};

  const handler = () => {
    callback(isFullscreen());
  };

  document.addEventListener('fullscreenchange', handler);
  document.addEventListener('webkitfullscreenchange', handler);
  document.addEventListener('mozfullscreenchange', handler);
  document.addEventListener('MSFullscreenChange', handler);

  return () => {
    document.removeEventListener('fullscreenchange', handler);
    document.removeEventListener('webkitfullscreenchange', handler);
    document.removeEventListener('mozfullscreenchange', handler);
    document.removeEventListener('MSFullscreenChange', handler);
  };
}
