import { BossEntity, BossType } from '../types.ts';

export class BossFactory {
  public static createBoss(stage: number, arenaWidth: number): BossEntity {
    const cycle = Math.floor((stage - 1) / 4) + 1;
    const stageInCycle = ((stage - 1) % 4) + 1;

    let type: BossType = 'SHORT_WASP';
    let baseTitle = '做空巨蜂 · WASP QUEEN';
    let baseHp = 2200;
    let size = 32;
    let color = '#ffd600';

    if (stageInCycle === 2) {
      type = 'REAPER_UFO';
      baseTitle = '機構收割母艦 · DREADNOUGHT UFO';
      baseHp = 4800;
      size = 36;
      color = '#00e5ff';
    } else if (stageInCycle === 3) {
      type = 'WHALE_KING';
      baseTitle = '萬億深海巨鯨 · CYBER LEVIATHAN';
      baseHp = 8800;
      size = 44;
      color = '#00b0ff';
    } else if (stageInCycle === 4) {
      type = 'BLACK_SWAN_OMEGA';
      baseTitle = '末日黑天鵝魔皇 · OMEGA SPECTRE';
      baseHp = 14000;
      size = 40;
      color = '#d500f9';
    }

    const hpMult = 1.0 + (cycle - 1) * 1.10;
    const dmgMult = 1.0 + (cycle - 1) * 0.30;
    const speedMult = Math.min(1.45, 1.0 + (cycle - 1) * 0.12);

    const hp = Math.floor(baseHp * hpMult);
    const title = cycle > 1 ? `【輪迴 ${cycle}】${baseTitle} Mk-${cycle}` : baseTitle;
    const hasLaser = type === 'REAPER_UFO' || type === 'BLACK_SWAN_OMEGA';

    return {
      id: `boss_${type}_${Date.now()}`,
      type,
      title,
      stage,
      cycle,
      damageMultiplier: dmgMult,
      whaleMobSpawnTimer: 0,
      siphonTendrilTimer: 0,
      x: arenaWidth / 2,
      y: -60,
      size,
      hp,
      maxHp: hp,
      color,
      state: 'ENTERING',
      stateTimer: 0,
      hoverBaseY: 130,
      hoverAngle: 0,
      hoverSpeed: (type === 'REAPER_UFO' ? 2.2 : (type === 'WHALE_KING' ? 1.2 : (type === 'BLACK_SWAN_OMEGA' ? 2.5 : 1.8))) * speedMult,
      diveStartX: arenaWidth / 2,
      diveStartY: 90,
      diveTargetX: arenaWidth / 2,
      diveTargetY: 600,
      diveControlX: arenaWidth / 2,
      diveControlY: 300,
      diveProgress: 0,
      shootTimer: 0,
      tractorBeamActive: false,
      tractorTimer: 0,
      hitFlashTimer: 0,
      laser: hasLaser ? {
        active: false,
        phase: 'NONE',
        timer: 0,
        startX: arenaWidth / 2,
        startY: 90,
        angle: Math.PI / 2,
        targetAngle: Math.PI / 2,
        sweepSpeed: 0,
        width: type === 'BLACK_SWAN_OMEGA' ? 26 : 22,
        damage: Math.round((type === 'BLACK_SWAN_OMEGA' ? 18 : 14) * dmgMult),
        color: type === 'BLACK_SWAN_OMEGA' ? '#d500f9' : '#00e5ff',
        glowColor: type === 'BLACK_SWAN_OMEGA' ? '#aa00ff' : '#00b0ff',
      } : undefined,
      laserAttackTimer: 0,
      healPulseTimer: 0,
      spreadWaveTimer: 0,
    };
  }
}
