import { getSurvivorPath2D } from '../data/icons.ts';

export class SurvivorRenderer {
  public render(ctx: CanvasRenderingContext2D, engine: any, dt: number): void {
    ctx.save();

    // 1. Cyber Trading Floor Dark Gradient Background
    const bgGrad = ctx.createRadialGradient(
      engine.width / 2, engine.height / 2, 30,
      engine.width / 2, engine.height / 2, Math.max(engine.width, engine.height) * 0.75
    );
    bgGrad.addColorStop(0, '#0c121d');
    bgGrad.addColorStop(1, '#070a0f');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, engine.width, engine.height);

    // 2. Ambient K-Line Candlestick Waves
    for (let i = 0; i < engine.bgCandles.length; i++) {
      const c = engine.bgCandles[i];
      c.x -= (dt / 1000) * 12;
      if (c.x < -30) {
        c.x = engine.width + 10;
        c.y = 80 + Math.random() * (engine.height - 180);
        c.h = 20 + Math.random() * 45;
        c.isUp = Math.random() > 0.48;
      }

      ctx.fillStyle = c.isUp ? 'rgba(0, 230, 118, 0.07)' : 'rgba(255, 23, 68, 0.07)';
      ctx.fillRect(c.x, c.y, 14, c.h);
      ctx.strokeStyle = c.isUp ? 'rgba(0, 230, 118, 0.12)' : 'rgba(255, 23, 68, 0.12)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(c.x + 7, c.y - 8);
      ctx.lineTo(c.x + 7, c.y + c.h + 8);
      ctx.stroke();
    }

    // 3. Grid Lines
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
    ctx.lineWidth = 1;
    for (let x = 0; x < engine.width; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, engine.height);
      ctx.stroke();
    }
    for (let y = 0; y < engine.height; y += 40) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(engine.width, y);
      ctx.stroke();
    }

    // 4. Render EXP Gems (Crypto Tokens)
    for (const g of engine.expGems) {
      ctx.save();
      ctx.translate(g.x, g.y);
      ctx.rotate(g.angle || 0);

      if (g.tier === 'BOSS') {
        // Mega Rainbow Diamond Gem
        ctx.shadowColor = '#e040fb';
        ctx.shadowBlur = 14;
        ctx.fillStyle = '#ff4081';
        ctx.beginPath();
        ctx.arc(0, 0, 8.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(-3, -3, 6, 6);
        ctx.fillStyle = '#00e5ff';
        ctx.fillRect(-1.5, -1.5, 3, 3);
      } else if (g.tier === 'ELITE') {
        // Ether Cyan Gem
        ctx.shadowColor = '#00e5ff';
        ctx.shadowBlur = 10;
        ctx.fillStyle = '#00b0ff';
        ctx.beginPath();
        ctx.arc(0, 0, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(-2, -2, 4, 4);
      } else {
        // Standard Gold / Mint Token
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 7;
        ctx.fillStyle = '#ffd700';
        ctx.beginPath();
        ctx.arc(0, 0, 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#2bd88e';
        ctx.fillRect(-1.5, -1.5, 3, 3);
      }
      ctx.restore();
    }

    // 5. Render Battlefield Pickups
    for (const p of engine.pickups) {
      ctx.save();
      const bobY = Math.sin(p.bobAngle) * 4;
      ctx.translate(p.x, p.y + bobY);

      if (p.life < 4000 && Math.floor(performance.now() / 140) % 2 === 0) {
        ctx.globalAlpha = 0.35;
      }

      let glowColor = '#00e676';
      if (p.type === 'ROCKET') glowColor = '#ff3d00';
      else if (p.type === 'NUKE') glowColor = '#ffd600';
      else if (p.type === 'FREEZE') glowColor = '#00e5ff';
      else if (p.type === 'PIZZA') glowColor = '#ff9100';
      else if (p.type === 'MAGNET') glowColor = '#e040fb';

      ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
      ctx.strokeStyle = glowColor;
      ctx.lineWidth = 2;
      ctx.shadowColor = glowColor;
      ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.arc(0, 0, 14, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      let iconKey: 'rocket' | 'nuke' | 'magnet' | 'pizza' | 'freeze' = 'magnet';
      if (p.type === 'ROCKET') iconKey = 'rocket';
      else if (p.type === 'NUKE') iconKey = 'nuke';
      else if (p.type === 'FREEZE') iconKey = 'freeze';
      else if (p.type === 'PIZZA') iconKey = 'pizza';

      const iconPath = getSurvivorPath2D(iconKey);
      if (iconPath) {
        ctx.save();
        ctx.scale(18 / 512, 18 / 512);
        ctx.translate(-256, -256);
        ctx.fillStyle = glowColor;
        ctx.fill(iconPath);
        ctx.restore();
      }
      ctx.restore();
    }

    // 6. Particle Systems
    engine.particleSystem.render(ctx);

    // 7. Render Player Projectiles (Liquidity Multi-Order Bullets)
    for (const p of engine.projectiles) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.fillStyle = '#69f0ae';
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(0, 0, 5, 0, Math.PI * 2);
      ctx.fill();

      // Incandescent pure white bullet impact core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(0, 0, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 8. Render Boss UFO Tractor Beam
    if (engine.currentBoss?.tractorBeamActive) {
      const boss = engine.currentBoss;
      ctx.save();
      const grad = ctx.createLinearGradient(boss.x, boss.y, boss.x, engine.height);
      grad.addColorStop(0, 'rgba(0, 229, 255, 0.45)');
      grad.addColorStop(0.5, 'rgba(224, 64, 251, 0.35)');
      grad.addColorStop(1, 'rgba(0, 229, 255, 0.08)');

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(boss.x - 20, boss.y + 10);
      ctx.lineTo(boss.x + 20, boss.y + 10);
      ctx.lineTo(boss.x + 95, engine.height);
      ctx.lineTo(boss.x - 95, engine.height);
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = 'rgba(0, 229, 255, 0.6)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([8, 6]);
      ctx.lineDashOffset = -performance.now() / 25;
      ctx.stroke();

      // Pulsing horizontal grid scanlines
      const scanPhase = (performance.now() / 30) % 25;
      ctx.strokeStyle = 'rgba(0, 229, 255, 0.28)';
      ctx.lineWidth = 1.2;
      ctx.setLineDash([]);
      for (let sy = boss.y + 20 + scanPhase; sy < engine.height; sy += 25) {
        const progress = (sy - boss.y) / (engine.height - boss.y);
        const spanW = 20 + (95 - 20) * progress;
        ctx.beginPath();
        ctx.moveTo(boss.x - spanW, sy);
        ctx.lineTo(boss.x + spanW, sy);
        ctx.stroke();
      }
      ctx.restore();
    }

    // 8.5 Render Boss Sweep Laser Beam
    if (engine.currentBoss?.laser?.active) {
      const laser = engine.currentBoss.laser;
      ctx.save();
      const startX = laser.startX;
      const startY = laser.startY;
      const beamLength = 1200;
      const endX = startX + Math.cos(laser.angle) * beamLength;
      const endY = startY + Math.sin(laser.angle) * beamLength;

      if (laser.phase === 'AIMING') {
        const flash = Math.floor(performance.now() / 80) % 2 === 0;
        ctx.strokeStyle = flash ? 'rgba(255, 23, 68, 0.85)' : 'rgba(0, 229, 255, 0.45)';
        ctx.lineWidth = 1.8;
        ctx.setLineDash([8, 6]);
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Warning targeting reticle circle around player
        ctx.setLineDash([]);
        ctx.strokeStyle = '#ff1744';
        ctx.lineWidth = 1.8;
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(engine.px, engine.py, engine.playerSize * 1.6, 0, Math.PI * 2);
        ctx.stroke();
      } else if (laser.phase === 'FIRING') {
        // Broad outer plasma glow
        ctx.strokeStyle = laser.glowColor;
        ctx.lineWidth = laser.width + 10;
        ctx.shadowColor = laser.glowColor;
        ctx.shadowBlur = 24;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Pure white core laser
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = Math.max(4, laser.width * 0.38);
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Firing Muzzle Flare at Boss bottom
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = laser.glowColor;
        ctx.shadowBlur = 16;
        ctx.beginPath();
        ctx.arc(startX, startY, laser.width * 0.9, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = laser.glowColor;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(startX, startY, laser.width * 1.4, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.restore();
    }

    // 8.6 Render Boss Bullets
    for (const b of engine.bossBullets) {
      ctx.save();
      ctx.translate(b.x, b.y);

      if (b.type === 'CRESCENT_SLASH') {
        // Glowing Crescent Blade (Wasp & Spectre)
        ctx.rotate(b.angle || 0);
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 20;
        ctx.fillStyle = b.color;

        // Draw curved crescent blade shape
        ctx.beginPath();
        ctx.arc(0, -6, 24, 0.25 * Math.PI, 0.75 * Math.PI, false);
        ctx.arc(0, 7, 16, 0.82 * Math.PI, 0.18 * Math.PI, true);
        ctx.closePath();
        ctx.fill();

        // Sharp white cutting edge highlight
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2.2;
        ctx.beginPath();
        ctx.arc(0, -6, 24, 0.28 * Math.PI, 0.72 * Math.PI, false);
        ctx.stroke();
        ctx.restore();
        continue;
      }

      if (b.type === 'SPREAD_ORB') {
        // Nova Floral Spread Orb (Whale King Lifesteal)
        ctx.shadowColor = b.isLifesteal ? '#00e676' : b.glowColor;
        ctx.shadowBlur = 16;
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();

        // Concentric ripple aura (green for lifesteal)
        ctx.strokeStyle = b.isLifesteal ? 'rgba(0, 230, 118, 0.85)' : b.glowColor;
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius * 1.5, 0, Math.PI * 2);
        ctx.stroke();

        // Core white bullet center
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, b.radius * 0.45, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        continue;
      }

      ctx.fillStyle = b.color;
      ctx.shadowColor = b.glowColor;
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 9. Render Orbit Burn Shield (Options Hedging Shield)
    const orbitCount = engine.weaponManager ? engine.weaponManager.orbiter.count : engine.orbitCount;
    const orbitAngle = engine.weaponManager ? engine.weaponManager.orbiter.angle : engine.orbitAngle;
    const orbitRadius = 45;

    if (orbitCount > 0) {
      // Faint defensive golden orbit ring around player
      ctx.save();
      ctx.strokeStyle = 'rgba(255, 214, 0, 0.22)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([4, 6]);
      ctx.beginPath();
      ctx.arc(engine.px, engine.py, orbitRadius, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    for (let o = 0; o < orbitCount; o++) {
      const angle = orbitAngle + (o * Math.PI * 2) / orbitCount;
      const ox = engine.px + Math.cos(angle) * orbitRadius;
      const oy = engine.py + Math.sin(angle) * orbitRadius;

      ctx.save();
      ctx.translate(ox, oy);
      ctx.rotate(angle + Math.PI / 2); // face outwards

      // 1. Fiery protective aura behind shield
      ctx.shadowColor = '#ff3d00';
      ctx.shadowBlur = 14;
      ctx.fillStyle = 'rgba(255, 145, 0, 0.35)';
      ctx.beginPath();
      ctx.arc(0, 0, 13, 0, Math.PI * 2);
      ctx.fill();

      // 2. SVG Hedge Options Shield Path2D
      const shieldPath = getSurvivorPath2D('shield');
      if (shieldPath) {
        ctx.scale(20 / 512, 20 / 512);
        ctx.translate(-256, -256);
        ctx.fillStyle = '#ffd600';
        ctx.shadowColor = '#ff6d00';
        ctx.shadowBlur = 12;
        ctx.fill(shieldPath);

        // Silver/White edge stroke
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 14;
        ctx.shadowBlur = 0;
        ctx.stroke(shieldPath);
      } else {
        ctx.fillStyle = '#ffd600';
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    // 10. Render Normal & Elite Enemies
    for (const e of engine.enemies) {
      ctx.save();
      ctx.translate(e.x, e.y);

      if (e.isElite) {
        ctx.save();
        const auraPhase = (performance.now() / 400) % Math.PI;
        const pulseRadius = (e.auraRadius || 160) * (0.88 + Math.sin(auraPhase) * 0.12);
        ctx.strokeStyle = 'rgba(255, 215, 0, 0.35)';
        ctx.lineWidth = 2;
        ctx.setLineDash([8, 8]);
        ctx.lineDashOffset = -performance.now() / 40;
        ctx.beginPath();
        ctx.arc(0, 0, pulseRadius, 0, Math.PI * 2);
        ctx.stroke();

        // Elite golden indicator aura under monster
        ctx.fillStyle = 'rgba(255, 215, 0, 0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, e.size * 1.6, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      if (e.type === 'RED_CANDLE') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#ff1744';
        ctx.shadowBlur = 10;

        // K-line candlestick upper & lower shadow wick lines
        ctx.strokeStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#ff8a80';
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.moveTo(0, -e.size / 2 - 6);
        ctx.lineTo(0, e.size / 2 + 6);
        ctx.stroke();

        const cPath = getSurvivorPath2D('candle');
        if (cPath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#ff1744';
          ctx.fill(cPath);
        } else {
          ctx.fillStyle = engine.freezeTimer > 0 ? '#00b0ff' : '#d50000';
          ctx.fillRect(-e.size / 2, -e.size / 2, e.size, e.size * 1.6);
        }
      } else if (e.type === 'LIQUIDATION_REAPER') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#e040fb';
        ctx.shadowBlur = 12;
        const reaperPath = getSurvivorPath2D('reaper');
        if (reaperPath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#e040fb';
          ctx.fill(reaperPath);
        } else {
          ctx.fillStyle = '#e040fb';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else if (e.type === 'FLASH_BEETLE') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#c6ff00';
        ctx.shadowBlur = 12;
        const beetlePath = getSurvivorPath2D('beetle');
        if (beetlePath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#c6ff00';
          ctx.fill(beetlePath);
        } else {
          ctx.fillStyle = '#c6ff00';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else if (e.type === 'BLACK_SWAN') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#7c4dff';
        ctx.shadowBlur = 18;
        ctx.globalAlpha = 0.85 + Math.sin(engine.elapsedTime * 4) * 0.15;
        const spectrePath = getSurvivorPath2D('spectre');
        if (spectrePath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#b388ff';
          ctx.fill(spectrePath);
        } else {
          ctx.fillStyle = '#7c4dff';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else {
        // BEAR
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#ff1744';
        ctx.shadowBlur = 12;
        ctx.fillStyle = engine.freezeTimer > 0 ? 'rgba(0, 229, 255, 0.25)' : 'rgba(213, 0, 0, 0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, e.size, 0, Math.PI * 2);
        ctx.fill();

        const bearPath = getSurvivorPath2D('bear');
        if (bearPath) {
          ctx.scale((e.size * 2) / 512, (e.size * 2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#d50000';
          ctx.fill(bearPath);
        }
      }
      ctx.restore();
    }

    // 10.5 Render Boss Entity & Siphon Auras
    if (engine.currentBoss) {
      const b = engine.currentBoss;

      if (b.type === 'WHALE_KING') {
        const mouthX = b.x;
        const mouthY = b.y + b.size * 0.4;
        const suctionRadius = 240;

        ctx.save();
        const timeSec = performance.now() / 1000;
        const ripple1 = (timeSec * 65) % suctionRadius;
        const ripple2 = ((timeSec * 65) + suctionRadius * 0.5) % suctionRadius;

        ctx.strokeStyle = 'rgba(0, 229, 255, 0.22)';
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.arc(mouthX, mouthY, suctionRadius - ripple1, 0, Math.PI * 2);
        ctx.stroke();

        ctx.strokeStyle = 'rgba(0, 230, 118, 0.25)';
        ctx.lineWidth = 2.0;
        ctx.beginPath();
        ctx.arc(mouthX, mouthY, suctionRadius - ripple2, 0, Math.PI * 2);
        ctx.stroke();

        ctx.strokeStyle = 'rgba(0, 176, 255, 0.35)';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([8, 6]);
        ctx.lineDashOffset = -timeSec * 35;
        ctx.beginPath();
        ctx.arc(mouthX, mouthY, suctionRadius, 0, Math.PI * 2);
        ctx.stroke();

        // Render Siphon Tendrils connecting Whale King to nearby retail enemies
        const nearby: any[] = [];
        for (let j = 0; j < engine.enemies.length; j++) {
          const e = engine.enemies[j];
          if (e.isBoss) continue;
          const d = Math.hypot(mouthX - e.x, mouthY - e.y);
          if (d < suctionRadius + 20) {
            nearby.push(e);
          }
        }
        nearby.sort((a, bMob) => Math.hypot(mouthX - a.x, mouthY - a.y) - Math.hypot(mouthX - bMob.x, mouthY - bMob.y));
        const tethered = nearby.slice(0, 3);

        ctx.setLineDash([6, 4]);
        ctx.lineDashOffset = -timeSec * 60;
        for (const e of tethered) {
          ctx.strokeStyle = 'rgba(0, 230, 118, 0.75)';
          ctx.lineWidth = 2.2;
          ctx.shadowColor = '#00e676';
          ctx.shadowBlur = 12;

          ctx.beginPath();
          ctx.moveTo(mouthX, mouthY);
          const midX = (mouthX + e.x) / 2 + Math.sin(timeSec * 8 + e.x) * 12;
          const midY = (mouthY + e.y) / 2 + Math.cos(timeSec * 8 + e.y) * 12;
          ctx.quadraticCurveTo(midX, midY, e.x, e.y);
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(e.x, e.y, e.size + 4, 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.restore();
      }

      ctx.save();
      ctx.translate(b.x, b.y);

      if (b.state === 'DIVING') {
        const diveAngle = Math.atan2(b.diveTargetY - b.y, b.diveTargetX - b.x) - Math.PI / 2;
        ctx.rotate(diveAngle);
      } else if (b.state === 'PREPARE_DIVE') {
        const shake = (Math.random() - 0.5) * 6;
        ctx.translate(shake, 0);
      }

      const isFlashing = b.hitFlashTimer > 0;
      ctx.shadowColor = isFlashing ? '#ffffff' : b.color;
      ctx.shadowBlur = isFlashing ? 28 : 22;

      const auraPulse = Math.sin(performance.now() / 120) * 4;
      ctx.strokeStyle = isFlashing ? '#ffffff' : b.color;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.arc(0, 0, b.size * 1.15 + auraPulse, 0, Math.PI * 2);
      ctx.stroke();

      // NG+ Cycle Prismatic Double Aura
      if (b.cycle && b.cycle > 1) {
        ctx.save();
        ctx.strokeStyle = 'rgba(255, 215, 0, 0.75)';
        ctx.lineWidth = 2.0;
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 14;
        ctx.setLineDash([8, 5]);
        ctx.lineDashOffset = performance.now() / 25;
        ctx.beginPath();
        ctx.arc(0, 0, b.size * 1.35, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }

      if (b.healPulseTimer && b.healPulseTimer > 0) {
        const pulseRatio = b.healPulseTimer / 600;
        ctx.save();
        ctx.strokeStyle = `rgba(0, 230, 118, ${pulseRatio * 0.9})`;
        ctx.lineWidth = 3;
        ctx.shadowColor = '#00e676';
        ctx.shadowBlur = 18;
        ctx.beginPath();
        ctx.arc(0, 0, b.size * (1.2 + (1 - pulseRatio) * 0.7), 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }

      let iconKey: 'bee' | 'ufo' | 'whale' | 'spectre' = 'bee';
      if (b.type === 'REAPER_UFO') iconKey = 'ufo';
      else if (b.type === 'WHALE_KING') iconKey = 'whale';
      else if (b.type === 'BLACK_SWAN_OMEGA') iconKey = 'spectre';

      const bossPath = getSurvivorPath2D(iconKey);
      if (bossPath) {
        ctx.save();
        const scale = (b.size * 2.3) / 512;
        ctx.scale(scale, scale);
        ctx.translate(-256, -256);
        ctx.fillStyle = isFlashing ? '#ffffff' : b.color;
        ctx.fill(bossPath);
        ctx.restore();
      } else {
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(0, 0, b.size, 0, Math.PI * 2);
        ctx.fill();
      }

      const crownPath = getSurvivorPath2D('crown');
      if (crownPath) {
        ctx.save();
        ctx.translate(0, -b.size * 0.95);
        ctx.scale(18 / 512, 18 / 512);
        ctx.translate(-256, -256);
        ctx.fillStyle = '#ffd700';
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 10;
        ctx.fill(crownPath);
        ctx.restore();
      }

      ctx.restore();
    }

    // 11. Render Player (SNEK Mascot Face)
    ctx.save();
    ctx.translate(engine.px, engine.py);

    if (engine.invulnerableTimer > 0 && Math.floor(performance.now() / 80) % 2 === 0) {
      ctx.globalAlpha = 0.45;
    }

    if (engine.rocketTimer > 0) {
      ctx.strokeStyle = '#ff3d00';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#ff6d00';
      ctx.shadowBlur = 16;
      ctx.beginPath();
      ctx.arc(0, 0, engine.playerSize * 1.5, 0, Math.PI * 2);
      ctx.stroke();
    } else {
      ctx.strokeStyle = engine.isFever ? 'rgba(255, 215, 0, 0.8)' : 'rgba(0, 230, 118, 0.4)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(0, 0, engine.playerSize * 1.35, 0, Math.PI * 2);
      ctx.stroke();
    }

    if (engine.imageLoaded && engine.headImage.complete) {
      const renderSize = engine.playerSize * 2.2;
      ctx.drawImage(engine.headImage, -renderSize / 2, -renderSize / 2, renderSize, renderSize);
    } else {
      ctx.fillStyle = '#4ade80';
      ctx.beginPath();
      ctx.arc(0, 0, engine.playerSize, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    // 12. Floating Heal Texts
    for (const ft of engine.bossFloatingTexts) {
      ctx.save();
      const alpha = Math.max(0, ft.life / ft.maxLife);
      ctx.fillStyle = ft.color;
      ctx.globalAlpha = alpha;
      ctx.font = '900 13px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.shadowColor = ft.color;
      ctx.shadowBlur = 8;
      ctx.fillText(ft.text, ft.x, ft.y);
      ctx.restore();
    }

    // 13. Siphon Energy Orbs
    for (const orb of engine.siphonOrbs) {
      ctx.save();
      const alpha = Math.max(0, 1 - orb.progress);
      ctx.fillStyle = orb.color;
      ctx.globalAlpha = alpha;
      ctx.shadowColor = orb.color;
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(orb.x, orb.y, 4.5, 0, Math.PI * 2);
      ctx.fill();

      // Incandescent pure white energy essence core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(orb.x, orb.y, 2.0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 14. Arcade Mega Boss Health Bar at Top
    if (engine.currentBoss && engine.bossWarningTimer <= 0) {
      const b = engine.currentBoss;
      ctx.save();
      const barW = Math.min(320, engine.width - 32);
      const barH = 9;
      const barX = (engine.width - barW) / 2;
      const barY = 20;

      ctx.fillStyle = 'rgba(10, 15, 26, 0.9)';
      ctx.fillRect(barX - 2, barY - 2, barW + 4, barH + 4);
      ctx.strokeStyle = b.color;
      ctx.lineWidth = 1.5;
      ctx.shadowColor = b.color;
      ctx.shadowBlur = 12;
      ctx.strokeRect(barX - 2, barY - 2, barW + 4, barH + 4);

      const ratio = Math.max(0, Math.min(1.0, b.hp / b.maxHp));
      const fillW = Math.round(barW * ratio);
      if (fillW > 0) {
        const hpGrad = ctx.createLinearGradient(barX, barY, barX + barW, barY);
        hpGrad.addColorStop(0, '#ff1744');
        hpGrad.addColorStop(0.5, b.color);
        hpGrad.addColorStop(1, '#ffffff');
        ctx.fillStyle = hpGrad;
        ctx.fillRect(barX, barY, fillW, barH);
      }

      ctx.shadowBlur = 0;
      ctx.font = '900 11px system-ui, sans-serif';
      ctx.textAlign = 'left';
      ctx.fillStyle = b.color;
      ctx.fillText(b.title, barX, barY - 5);

      ctx.textAlign = 'right';
      ctx.font = '700 10px system-ui, sans-serif';
      ctx.fillStyle = '#f8fafc';
      ctx.fillText(`${Math.ceil(b.hp)} / ${b.maxHp}`, barX + barW, barY - 5);
      ctx.restore();
    }

    // 15. Boss Approaching Warning Banner
    if (engine.bossWarningTimer > 0) {
      ctx.save();
      const bannerY = engine.height / 2 - 38;
      const bannerH = 76;
      const flash = Math.floor(performance.now() / 120) % 2 === 0;

      ctx.fillStyle = flash ? 'rgba(183, 28, 28, 0.94)' : 'rgba(136, 14, 79, 0.94)';
      ctx.fillRect(0, bannerY, engine.width, bannerH);

      ctx.strokeStyle = '#ffd600';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#ff6d00';
      ctx.shadowBlur = 14;
      ctx.strokeRect(0, bannerY, engine.width, bannerH);

      ctx.textAlign = 'center';
      ctx.font = '900 16px system-ui, sans-serif';
      ctx.fillStyle = '#ffd600';
      ctx.shadowColor = '#ff6d00';
      ctx.shadowBlur = 12;
      ctx.fillText('⚠️ WARNING: BOSS APPROACHING ⚠️', engine.width / 2, bannerY + 28);

      ctx.font = '700 12px system-ui, sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.shadowBlur = 6;
      ctx.fillText('GALAGA AIR RAID DETECTED', engine.width / 2, bannerY + 54);
      ctx.restore();
    }

    // 16. Stage Clear Victory Banner
    if (engine.stageClearTimer > 0) {
      ctx.save();
      const bannerY = engine.height / 2 - 40;
      const bannerH = 80;

      ctx.fillStyle = 'rgba(6, 78, 59, 0.94)';
      ctx.fillRect(0, bannerY, engine.width, bannerH);

      ctx.strokeStyle = '#10b981';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#34d399';
      ctx.shadowBlur = 14;
      ctx.strokeRect(0, bannerY, engine.width, bannerH);

      ctx.textAlign = 'center';
      ctx.font = '900 18px system-ui, sans-serif';
      ctx.fillStyle = '#a7f3d0';
      ctx.fillText(`🏆 ${engine.stageClearTitle}`, engine.width / 2, bannerY + 32);

      const cycle = Math.floor((engine.stage - 1) / 4) + 1;
      const cycleText = cycle > 1 ? ` (輪迴 ${cycle})` : '';

      ctx.font = '700 12px system-ui, sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.shadowBlur = 0;
      ctx.fillText(`STAGE ${engine.stage}${cycleText} NOW COMMENCING`, engine.width / 2, bannerY + 58);
      ctx.restore();
    }

    // 16.5 Stage & Macro Event Alert Banner
    if (engine.stageAlert && engine.stageAlert.timer > 0) {
      ctx.save();
      const elapsed = engine.stageAlert.maxTimer - engine.stageAlert.timer;
      let alpha = 1.0;
      if (elapsed < 0.3) {
        alpha = Math.max(0.3, elapsed / 0.3);
      } else if (engine.stageAlert.timer < 0.4) {
        alpha = Math.max(0, engine.stageAlert.timer / 0.4);
      }
      ctx.globalAlpha = alpha;

      const bannerY = engine.height / 2 - 36;
      ctx.fillStyle = 'rgba(6, 10, 18, 0.92)';
      ctx.fillRect(0, bannerY, engine.width, 70);

      ctx.strokeStyle = '#ffd700';
      ctx.lineWidth = 2;
      ctx.shadowColor = '#ffd700';
      ctx.shadowBlur = 16;
      ctx.strokeRect(0, bannerY, engine.width, 70);

      ctx.textAlign = 'center';
      ctx.font = '900 15px system-ui, sans-serif';
      ctx.fillStyle = '#ffd700';
      ctx.fillText(engine.stageAlert.title, engine.width / 2, bannerY + 28);

      ctx.font = '500 11px system-ui, sans-serif';
      ctx.fillStyle = '#cbd5e1';
      ctx.shadowBlur = 0;
      ctx.fillText(engine.stageAlert.subtitle, engine.width / 2, bannerY + 52);
      ctx.restore();
    }

    // 17. Nuke Screen Flash
    if (engine.nukeFlashTimer > 0) {
      ctx.save();
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.min(0.85, engine.nukeFlashTimer * 2.5)})`;
      ctx.fillRect(0, 0, engine.width, engine.height);
      ctx.restore();
    }

    ctx.restore();
  }
}
