import { SoundManager } from '../../audio/SoundManager.ts';
import { ParticleSystem } from '../../engine/ParticleSystem.ts';

export interface Platform {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
  type: 'GREEN_CANDLE' | 'RED_BROKEN' | 'ADA_ROCKET' | 'MOVING_CLOUD';
  broken?: boolean;
  vx?: number;
  startX?: number;
}

export interface MoonRunCallbacks {
  onAltitudeChange: (altitudeMeters: number, maxAltitude: number) => void;
  onGameOver: (altitudeMeters: number) => void;
}

export class MoonRunEngine {
  public canvas: HTMLCanvasElement;
  public ctx: CanvasRenderingContext2D;
  private callbacks: MoonRunCallbacks;
  public soundManager: SoundManager;
  public particleSystem: ParticleSystem;

  // Viewport
  public width: number = 440;
  public height: number = 560;

  // Player (Snek)
  public px: number = 220;
  public py: number = 400;
  public pvx: number = 0;
  public pvy: number = 0;
  public playerSize: number = 18;
  public isRocketBoosting: boolean = false;
  private rocketTimer: number = 0;

  // Physics constants
  private readonly gravity: number = 0.38;
  private readonly jumpForce: number = -10.5;
  private readonly rocketForce: number = -22;

  // Camera & Progression
  public cameraY: number = 0;
  public highestAltitude: number = 0;
  public currentAltitude: number = 0;

  // Platforms
  public platforms: Platform[] = [];
  private nextPlatformY: number = 0;

  // State
  public isRunning: boolean = false;
  private lastTime: number = 0;
  private animFrameId: number | null = null;

  // Mascot sprite
  private mascotImg: HTMLImageElement = new Image();
  private imageLoaded: boolean = false;

  constructor(canvas: HTMLCanvasElement, callbacks: MoonRunCallbacks) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('No 2D context');
    this.ctx = ctx;
    this.callbacks = callbacks;
    this.soundManager = new SoundManager();
    this.particleSystem = new ParticleSystem();

    this.mascotImg.src = './assets/face/SNEK_0002.webp';
    this.mascotImg.onload = () => {
      this.imageLoaded = true;
    };

    this.initCanvasSize();
  }

  private initCanvasSize(): void {
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    this.ctx.scale(dpr, dpr);
  }

  public start(): void {
    this.soundManager.unlock();
    this.px = this.width / 2;
    this.py = 460;
    this.pvx = 0;
    this.pvy = this.jumpForce;
    this.cameraY = 0;
    this.highestAltitude = 0;
    this.currentAltitude = 0;
    this.isRocketBoosting = false;
    this.rocketTimer = 0;

    this.particleSystem.clear();
    this.initPlatforms();

    this.isRunning = true;
    this.lastTime = performance.now();
    this.callbacks.onAltitudeChange(0, 0);

    this.loop(this.lastTime);
  }

  public setHorizontalMove(dir: -1 | 0 | 1): void {
    const speed = 4.8;
    this.pvx = dir * speed;
  }

  private initPlatforms(): void {
    this.platforms = [];
    // Base starter platform
    this.platforms.push({
      id: 'plat_0',
      x: this.width / 2 - 40,
      y: 500,
      w: 80,
      h: 14,
      type: 'GREEN_CANDLE',
    });

    this.nextPlatformY = 440;
    while (this.nextPlatformY > -300) {
      this.spawnPlatform(this.nextPlatformY);
      this.nextPlatformY -= 55 + Math.random() * 25;
    }
  }

  private spawnPlatform(y: number): void {
    const rand = Math.random();
    let type: Platform['type'] = 'GREEN_CANDLE';
    let w = 70;

    if (rand < 0.12 && Math.abs(y) > 200) {
      type = 'ADA_ROCKET';
      w = 60;
    } else if (rand < 0.28 && Math.abs(y) > 300) {
      type = 'RED_BROKEN';
      w = 65;
    } else if (rand < 0.45 && Math.abs(y) > 150) {
      type = 'MOVING_CLOUD';
      w = 75;
    }

    const x = 20 + Math.random() * (this.width - w - 40);
    this.platforms.push({
      id: `plat_${y}_${Math.random()}`,
      x,
      y,
      w,
      h: 14,
      type,
      vx: type === 'MOVING_CLOUD' ? (Math.random() > 0.5 ? 1.5 : -1.5) : 0,
      startX: x,
    });
  }

  private loop = (timestamp: number): void => {
    if (!this.isRunning) return;

    const dt = timestamp - this.lastTime;
    this.lastTime = timestamp;

    this.update(dt);
    this.render();

    this.animFrameId = requestAnimationFrame(this.loop);
  };

  public destroy(): void {
    this.isRunning = false;
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
    }
  }

  private update(dt: number): void {
    this.particleSystem.update(dt);

    if (this.isRocketBoosting) {
      this.rocketTimer -= dt;
      this.particleSystem.emitBurnDash(this.px, this.py + 10, -Math.PI / 2);
      if (this.rocketTimer <= 0) {
        this.isRocketBoosting = false;
      }
    }

    // 1. Apply Physics
    if (!this.isRocketBoosting) {
      this.pvy += this.gravity;
    }
    this.px += this.pvx;
    this.py += this.pvy;

    // 2. Screen Wrap (Left <-> Right)
    if (this.px < -10) {
      this.px = this.width + 10;
    } else if (this.px > this.width + 10) {
      this.px = -10;
    }

    // 3. Move Moving Clouds
    for (const p of this.platforms) {
      if (p.type === 'MOVING_CLOUD' && p.vx) {
        p.x += p.vx;
        if (p.x <= 10 || p.x + p.w >= this.width - 10) {
          p.vx = -p.vx;
        }
      }
    }

    // 4. Platform Collision (Only when falling down)
    if (this.pvy > 0 && !this.isRocketBoosting) {
      for (const p of this.platforms) {
        if (p.broken) continue;

        if (
          this.px + this.playerSize * 0.7 > p.x &&
          this.px - this.playerSize * 0.7 < p.x + p.w &&
          this.py + this.playerSize >= p.y &&
          this.py + this.playerSize <= p.y + p.h + this.pvy + 3
        ) {
          // Landed on platform!
          this.py = p.y - this.playerSize;

          if (p.type === 'ADA_ROCKET') {
            this.isRocketBoosting = true;
            this.rocketTimer = 2200;
            this.pvy = this.rocketForce;
            this.soundManager.playAda();
            this.particleSystem.emitSuperEat(this.px, this.py);
          } else if (p.type === 'RED_BROKEN') {
            p.broken = true;
            this.pvy = this.jumpForce * 0.75;
            this.soundManager.playDie();
            this.particleSystem.emitDeath(p.x + p.w / 2, p.y + p.h / 2);
          } else {
            this.pvy = this.jumpForce;
            this.soundManager.playEat();
            this.particleSystem.emitEat(this.px, this.py + this.playerSize);
          }
          break;
        }
      }
    }

    // 5. Smooth Camera Tracking
    const screenTopThreshold = this.height * 0.45;
    if (this.py - this.cameraY < screenTopThreshold) {
      this.cameraY = this.py - screenTopThreshold;
    }

    // 6. Calculate Altitude (Meters to Moon)
    this.currentAltitude = Math.max(0, Math.floor(-this.cameraY / 6));
    if (this.currentAltitude > this.highestAltitude) {
      this.highestAltitude = this.currentAltitude;
      this.callbacks.onAltitudeChange(this.currentAltitude, this.highestAltitude);
    }

    // 7. Recycle Platforms
    while (this.nextPlatformY > this.cameraY - 200) {
      this.spawnPlatform(this.nextPlatformY);
      this.nextPlatformY -= 55 + Math.random() * 25;
    }

    // Remove platforms far below
    for (let i = this.platforms.length - 1; i >= 0; i--) {
      if (this.platforms[i].y > this.cameraY + this.height + 100) {
        this.platforms.splice(i, 1);
      }
    }

    // 8. Check Fall Game Over
    if (this.py - this.cameraY > this.height + 50) {
      this.handleGameOver();
    }
  }

  private handleGameOver(): void {
    this.isRunning = false;
    this.soundManager.playDie();
    this.callbacks.onGameOver(this.highestAltitude);
  }

  private render(): void {
    const ctx = this.ctx;
    ctx.save();

    // 1. Cyber Space Dark Gradient (Darker as altitude rises)
    const altitudeFactor = Math.min(1, this.highestAltitude / 2000);
    const grad = ctx.createLinearGradient(0, 0, 0, this.height);
    grad.addColorStop(0, '#05070a');
    grad.addColorStop(1, altitudeFactor > 0.5 ? '#060a12' : '#0b0e17');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, this.width, this.height);

    // 2. Stars / Moon Background
    ctx.fillStyle = '#ffffff';
    for (let i = 0; i < 20; i++) {
      const sx = ((i * 73) % this.width);
      const sy = ((i * 127 - this.cameraY * 0.2) % this.height + this.height) % this.height;
      ctx.globalAlpha = 0.3 + (i % 5) * 0.12;
      ctx.fillRect(sx, sy, 2, 2);
    }
    ctx.globalAlpha = 1;

    // Camera offset
    ctx.save();
    ctx.translate(0, -this.cameraY);

    // 3. Render Particles
    this.particleSystem.render(ctx);

    // 4. Render Platforms
    for (const p of this.platforms) {
      if (p.broken) continue;

      ctx.save();
      if (p.type === 'GREEN_CANDLE') {
        // Green Candlestick
        ctx.fillStyle = '#00e676';
        ctx.shadowColor = '#00e676';
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.roundRect(p.x, p.y, p.w, p.h, 6);
        ctx.fill();

        // Candlestick Wick line
        ctx.strokeStyle = '#69f0ae';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(p.x + p.w / 2, p.y - 4);
        ctx.lineTo(p.x + p.w / 2, p.y + p.h + 4);
        ctx.stroke();
      } else if (p.type === 'ADA_ROCKET') {
        // Golden Rocket Booster
        ctx.fillStyle = '#ffd700';
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.roundRect(p.x, p.y, p.w, p.h, 6);
        ctx.fill();

        // Booster badge
        ctx.fillStyle = '#000';
        ctx.font = 'bold 9px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('BOOST', p.x + p.w / 2, p.y + 10);
      } else if (p.type === 'RED_BROKEN') {
        // Red Crack
        ctx.fillStyle = '#ff1744';
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 6;
        ctx.beginPath();
        ctx.roundRect(p.x, p.y, p.w, p.h, 4);
        ctx.fill();

        // Crack line
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(p.x + p.w * 0.45, p.y);
        ctx.lineTo(p.x + p.w * 0.55, p.y + p.h);
        ctx.stroke();
      } else if (p.type === 'MOVING_CLOUD') {
        // Moving FUD Cloud
        ctx.fillStyle = '#00b0ff';
        ctx.shadowColor = '#00b0ff';
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.roundRect(p.x, p.y, p.w, p.h, 8);
        ctx.fill();
      }

      ctx.restore();
    }

    // 5. Render SNEK Player
    ctx.save();
    ctx.translate(this.px, this.py);

    if (this.isRocketBoosting) {
      // Golden Flame Trail
      ctx.shadowColor = '#ffd700';
      ctx.shadowBlur = 20;
    } else {
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 10;
    }

    if (this.imageLoaded && this.mascotImg.complete) {
      const s = this.playerSize * 2.2;
      ctx.drawImage(this.mascotImg, -s / 2, -s / 2, s, s);
    } else {
      ctx.fillStyle = '#00e676';
      ctx.beginPath();
      ctx.arc(0, 0, this.playerSize, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
    ctx.restore(); // restore camera offset
    ctx.restore(); // restore root
  }
}
