const path2dCache: Record<string, Path2D> = {};

export function getSurvivorPath2D(iconKey: string): Path2D | null {
  if (!SURVIVOR_ICON_PATHS[iconKey]) return null;
  if (typeof Path2D === 'undefined') return null;
  if (!path2dCache[iconKey]) {
    path2dCache[iconKey] = new Path2D(SURVIVOR_ICON_PATHS[iconKey]);
  }
  return path2dCache[iconKey];
}

export function getSurvivorSvg(iconKey: string, size: number = 24, fill: string = 'currentColor'): string {
  const d = SURVIVOR_ICON_PATHS[iconKey];
  if (!d) return '';
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="${size}" height="${size}" style="display:inline-block;vertical-align:middle;"><path fill="${fill}" d="${d}"/></svg>`;
}
