import { BossBullet, BossEntity, BossFloatingText, Enemy, SiphonOrb } from '../types.ts';

export interface BossCombatControllerOptions {
  arenaWidth: number;
  arenaHeight: number;
  onBossDefeated?: (boss: BossEntity) => void;
  onPlayerDamage?: (damage: number) => void;
  onPlaySound?: (sound: 'boost' | 'die') => void;
  onSpawnRetailMob?: (count: number) => void;
}

export class BossCombatController {
  public arenaWidth: number;
  public arenaHeight: number;
  public currentBoss: BossEntity | null = null;
  public bossBullets: BossBullet[] = [];
  public siphonOrbs: SiphonOrb[] = [];
  public bossFloatingTexts: BossFloatingText[] = [];

  private onBossDefeated?: (boss: BossEntity) => void;
  private onPlayerDamage?: (damage: number) => void;
  private onPlaySound?: (sound: 'boost' | 'die') => void;
  private onSpawnRetailMob?: (count: number) => void;

  constructor(options: BossCombatControllerOptions) {
    this.arenaWidth = options.arenaWidth;
    this.arenaHeight = options.arenaHeight;
    this.onBossDefeated = options.onBossDefeated;
    this.onPlayerDamage = options.onPlayerDamage;
    this.onPlaySound = options.onPlaySound;
    this.onSpawnRetailMob = options.onSpawnRetailMob;
  }

  public setBoss(boss: BossEntity | null): void {
    this.currentBoss = boss;
  }

  public checkBossDefeat(): boolean {
    if (this.currentBoss && this.currentBoss.hp <= 0) {
      const boss = this.currentBoss;
      this.currentBoss = null;
      this.onBossDefeated?.(boss);
      return true;
    }
    return false;
  }

  public triggerLaserAttack(boss: BossEntity, player: { x: number; y: number }): void {
    const startX = boss.x;
    const startY = boss.y + boss.size * 0.7;
    const angle = Math.atan2(player.y - startY, player.x - startX);

    if (!boss.laser) {
      boss.laser = {
        active: true,
        phase: 'AIMING',
        startX,
        startY,
        angle,
        targetAngle: angle,
        sweepSpeed: 0,
        timer: 1.2,
        width: 28,
        damage: 45,
        color: '#00e5ff',
        glowColor: '#00b0ff',
      };
    } else {
      boss.laser.active = true;
      boss.laser.phase = 'AIMING';
      boss.laser.timer = 1.2;
      boss.laser.startX = startX;
      boss.laser.startY = startY;
      boss.laser.angle = angle;
      boss.laser.width = 28;
    }
    this.onPlaySound?.('boost');
  }

  public fireBossAttack(boss: BossEntity, player: { x: number; y: number }): BossBullet[] {
    const bullets: BossBullet[] = [];
    const bx = boss.x;
    const by = boss.y + boss.size * 0.6;
    const dmgMult = boss.damageMultiplier || 1.0;

    if (boss.type === 'SHORT_WASP') {
      const angle = Math.atan2(player.y - by, player.x - bx);
      const speed = 4.6;
      for (const offset of [-0.22, 0.22]) {
        const slashAngle = angle + offset;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'CRESCENT_SLASH',
          x: bx,
          y: by,
          vx: Math.cos(slashAngle) * speed,
          vy: Math.sin(slashAngle) * speed,
          radius: 12,
          damage: Math.round(18 * dmgMult),
          color: '#ff1744',
          glowColor: '#ff9100',
          life: 4000,
          angle: slashAngle + Math.PI / 2,
          rotationSpeed: 3.5,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'WHALE_KING') {
      // 16-way radial flower spread bullets with lifesteal
      const count = 16;
      const speed = 3.8;
      for (let i = 0; i < count; i++) {
        const angle = (i * Math.PI * 2) / count;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'SPREAD_ORB',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 7.5,
          damage: Math.round(24 * dmgMult),
          color: '#00e5ff',
          glowColor: '#00b0ff',
          life: 4200,
          isLifesteal: true,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
      boss.spreadWaveTimer = 0.35; // Trigger Wave 2 delayed
    } else if (boss.type === 'REAPER_UFO') {
      const speed = 4.5;
      for (const spread of [-0.35, 0, 0.35]) {
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'STINGER',
          x: bx,
          y: by,
          vx: Math.sin(spread) * speed,
          vy: Math.cos(spread) * speed,
          radius: 6,
          damage: Math.round(22 * dmgMult),
          color: '#e040fb',
          glowColor: '#ea80fc',
          life: 3500,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'BLACK_SWAN_OMEGA') {
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      if (Math.random() < 0.5) {
        const angle = Math.atan2(player.y - by, player.x - bx);
        const speed = 4.8;
        for (const offset of [-0.32, 0.32]) {
          const slashAngle = angle + offset;
          const b: BossBullet = {
            id: `bb_${Date.now()}_${Math.random()}`,
            type: 'CRESCENT_SLASH',
            x: bx,
            y: by,
            vx: Math.cos(slashAngle) * speed,
            vy: Math.sin(slashAngle) * speed,
            radius: 14,
            damage: Math.round(32 * dmgMult),
            color: '#d500f9',
            glowColor: '#aa00ff',
            life: 4200,
            angle: slashAngle + Math.PI / 2,
            rotationSpeed: 4.2,
          };
          bullets.push(b);
          this.bossBullets.push(b);
        }
      } else {
        const count = isEnraged ? 8 : 6;
        const speed = isEnraged ? 4.2 : 3.8;
        for (let i = 0; i < count; i++) {
          const angle = (i * Math.PI * 2) / count;
          const b: BossBullet = {
            id: `bb_${Date.now()}_${Math.random()}`,
            type: 'SPIRAL_SWAN',
            x: bx,
            y: by,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            radius: 6.5,
            damage: Math.round(30 * dmgMult),
            color: '#d500f9',
            glowColor: '#aa00ff',
            life: 4000,
          };
          bullets.push(b);
          this.bossBullets.push(b);
        }
      }
    }

    this.onPlaySound?.('die');
    return bullets;
  }

  public devourRetailEnemy(
    idx: number,
    boss: BossEntity,
    enemies: Enemy[],
    isTendrilDrain: boolean = false
  ): void {
    const e = enemies[idx];
    if (!e) return;

    enemies.splice(idx, 1);

    const mult = boss.damageMultiplier || 1.0;
    const baseHeal = isTendrilDrain ? 80 : 150;
    const healAmount = Math.floor(baseHeal * mult);
    const actualHeal = Math.min(healAmount, boss.maxHp - boss.hp);

    if (actualHeal > 0) {
      boss.hp += actualHeal;
      boss.healPulseTimer = 550;
      this.onPlaySound?.('boost');

      this.bossFloatingTexts.push({
        id: `devour_${Date.now()}_${Math.random()}`,
        x: boss.x + (Math.random() - 0.5) * 24,
        y: boss.y - boss.size - 20,
        text: isTendrilDrain ? `+${actualHeal} 虹吸清算!` : `+${actualHeal} 割韭菜! 🩸`,
        color: '#00e676',
        life: 1300,
        maxLife: 1300,
        vy: -38,
      });

      // Spawn siphon energy orbs
      for (let i = 0; i < 3; i++) {
        this.siphonOrbs.push({
          x: e.x,
          y: e.y,
          startX: e.x,
          startY: e.y,
          targetX: boss.x,
          targetY: boss.y + boss.size * 0.4,
          progress: 0,
          color: '#00e676',
        });
      }
    }
  }

  public applyBossLifesteal(
    boss: BossEntity,
    amount: number,
    playerPos?: { x: number; y: number }
  ): void {
    const mult = boss.damageMultiplier || 1.0;
    const scaledAmount = Math.floor(amount * mult);
    const healed = Math.min(scaledAmount, boss.maxHp - boss.hp);
    if (healed <= 0) return;

    boss.hp += healed;
    boss.healPulseTimer = 600;

    this.bossFloatingTexts.push({
      id: `heal_${Date.now()}_${Math.random()}`,
      x: boss.x + (Math.random() - 0.5) * 20,
      y: boss.y - boss.size - 18,
      text: `+${healed} HP`,
      color: '#00e676',
      life: 1200,
      maxLife: 1200,
      vy: -35,
    });

    if (playerPos) {
      for (let i = 0; i < 4; i++) {
        this.siphonOrbs.push({
          x: playerPos.x + (Math.random() - 0.5) * 16,
          y: playerPos.y + (Math.random() - 0.5) * 16,
          startX: playerPos.x,
          startY: playerPos.y,
          targetX: boss.x,
          targetY: boss.y,
          progress: 0,
          color: '#00e676',
        });
      }
    }

    this.onPlaySound?.('boost');
  }

  public updateWhaleDevour(boss: BossEntity, enemies: Enemy[], dtSec: number = 0.016): void {
    const mouthX = boss.x;
    const mouthY = boss.y + boss.size * 0.4;
    const suctionRadius = 240;
    const devourRadius = boss.size + 16;

    for (let j = enemies.length - 1; j >= 0; j--) {
      const e = enemies[j];
      if (e.isBoss) continue;

      const dist = Math.hypot(mouthX - e.x, mouthY - e.y);
      if (dist < suctionRadius) {
        const pullRatio = 1 - dist / suctionRadius;
        const pullSpeed = 70 + pullRatio * 150;
        const angle = Math.atan2(mouthY - e.y, mouthX - e.x);
        e.x += Math.cos(angle) * pullSpeed * dtSec;
        e.y += Math.sin(angle) * pullSpeed * dtSec;

        if (dist < devourRadius) {
          this.devourRetailEnemy(j, boss, enemies);
          continue;
        }
      }
    }

    // Whale King Siphon Tendrils
    boss.siphonTendrilTimer = (boss.siphonTendrilTimer || 0) + dtSec;
    const nearbyEnemies: { enemy: Enemy; dist: number; index: number }[] = [];
    for (let j = 0; j < enemies.length; j++) {
      const e = enemies[j];
      if (e.isBoss) continue;
      const dist = Math.hypot(mouthX - e.x, mouthY - e.y);
      if (dist < suctionRadius + 30) {
        nearbyEnemies.push({ enemy: e, dist, index: j });
      }
    }
    nearbyEnemies.sort((a, bMob) => a.dist - bMob.dist);
    const tethered = nearbyEnemies.slice(0, 3);

    for (const t of tethered) {
      const drainDamage = 28 * dtSec;
      t.enemy.hp -= drainDamage;

      if (Math.random() < 0.2) {
        this.siphonOrbs.push({
          x: t.enemy.x,
          y: t.enemy.y,
          startX: t.enemy.x,
          startY: t.enemy.y,
          targetX: mouthX,
          targetY: mouthY,
          progress: 0,
          color: '#00e676',
        });
      }

      const healAmt = drainDamage * 0.75;
      boss.hp = Math.min(boss.maxHp, boss.hp + healAmt);

      if (t.enemy.hp <= 0) {
        const idx = enemies.indexOf(t.enemy);
        if (idx !== -1) {
          this.devourRetailEnemy(idx, boss, enemies, true);
        }
      }
    }
  }

  public update(
    dt: number,
    player: { x: number; y: number; size?: number },
    enemies: Enemy[] = [],
    invulnerableTimer: number = 0
  ): void {
    const boss = this.currentBoss;
    if (!boss) return;

    const dtSec = dt / 1000;
    boss.stateTimer += dtSec;
    if (boss.hitFlashTimer > 0) boss.hitFlashTimer -= dt;
    if (boss.healPulseTimer && boss.healPulseTimer > 0) boss.healPulseTimer -= dt;

    // Whale King Devour & Swarm Logic
    if (boss.type === 'WHALE_KING') {
      boss.whaleMobSpawnTimer = (boss.whaleMobSpawnTimer || 0) + dtSec;
      if (boss.whaleMobSpawnTimer >= 4.5) {
        boss.whaleMobSpawnTimer = 0;
        if (enemies.length < 20) {
          const spawnCount = 3 + Math.floor(Math.random() * 3);
          this.onSpawnRetailMob?.(spawnCount);
        }
      }

      this.updateWhaleDevour(boss, enemies, dtSec);

      // Delayed 2nd wave spread bullets
      if (boss.spreadWaveTimer && boss.spreadWaveTimer > 0) {
        boss.spreadWaveTimer -= dtSec;
        if (boss.spreadWaveTimer <= 0) {
          boss.spreadWaveTimer = 0;
          const speed = 3.6;
          const bx = boss.x;
          const by = boss.y + boss.size * 0.6;
          const dmgMult = boss.damageMultiplier || 1.0;
          for (let i = 0; i < 8; i++) {
            const spread = (i - 3.5) * 0.22;
            this.bossBullets.push({
              id: `bb_${Date.now()}_${Math.random()}`,
              type: 'SPREAD_ORB',
              x: bx,
              y: by,
              vx: Math.sin(spread) * speed,
              vy: Math.cos(spread) * speed,
              radius: 7.0,
              damage: Math.round(22 * dmgMult),
              color: '#80d8ff',
              glowColor: '#00e5ff',
              life: 4200,
              isLifesteal: true,
            });
          }
          this.onPlaySound?.('die');
        }
      }
    }

    // Laser Beam Logic
    if (boss.laser && boss.laser.active) {
      const laser = boss.laser;
      laser.startX = boss.x;
      laser.startY = boss.y + boss.size * 0.7;

      if (laser.phase === 'AIMING') {
        laser.timer -= dtSec;
        const targetAng = Math.atan2(player.y - laser.startY, player.x - laser.startX);
        laser.angle += (targetAng - laser.angle) * Math.min(1.0, dtSec * 4.5);

        if (laser.timer <= 0) {
          laser.phase = 'FIRING';
          laser.timer = 1.3;
          laser.sweepSpeed = player.x > boss.x ? 0.35 : -0.35;
          this.onPlaySound?.('die');
        }
      } else if (laser.phase === 'FIRING') {
        laser.timer -= dtSec;
        laser.angle += laser.sweepSpeed * dtSec;

        const cosA = Math.cos(laser.angle);
        const sinA = Math.sin(laser.angle);
        const vx = player.x - laser.startX;
        const vy = player.y - laser.startY;
        const proj = vx * cosA + vy * sinA;
        if (proj > 0 && proj < 1200) {
          const perpDist = Math.abs(vx * sinA - vy * cosA);
          const pSize = player.size ?? 18;
          if (perpDist < laser.width / 2 + pSize && invulnerableTimer <= 0) {
            this.onPlayerDamage?.(laser.damage);
          }
        }

        if (laser.timer <= 0) {
          laser.phase = 'NONE';
          laser.active = false;
        }
      }
    }

    // State Machine
    if (boss.state === 'ENTERING') {
      boss.y += 120 * dtSec;
      // Clamp target within mid-field spec (y ∈ [80, 360])
      const targetHoverBaseY = Math.max(80, Math.min(360, boss.hoverBaseY || 145));
      if (boss.y >= targetHoverBaseY) {
        boss.y = targetHoverBaseY;
        boss.hoverBaseY = targetHoverBaseY;
        boss.state = 'FORMATION_HOVER';
        boss.stateTimer = 0;
      }
      return;
    }

    if (boss.state === 'FORMATION_HOVER') {
      const isEnraged = boss.hp / boss.maxHp <= 0.4;
      const speedMult = isEnraged ? 1.25 : 1.0;
      boss.hoverAngle += boss.hoverSpeed * speedMult * dtSec;

      // Roaming AI: dynamic mid-field patrol (y ∈ [80, 360])
      const targetBaseY = Math.max(80, Math.min(360, 145 + Math.sin(boss.hoverAngle * 0.7) * 75));
      boss.hoverBaseY += (targetBaseY - boss.hoverBaseY) * Math.min(1.0, dtSec * 1.5);

      boss.x = this.arenaWidth / 2 + Math.cos(boss.hoverAngle) * (this.arenaWidth * 0.38);
      boss.y = Math.max(80, Math.min(360, boss.hoverBaseY + Math.sin(boss.hoverAngle * 1.8) * 22));

      // Regular Attack timer
      if (!boss.laser?.active) {
        boss.shootTimer += dtSec;
        let shootInterval =
          boss.type === 'BLACK_SWAN_OMEGA'
            ? 1.6
            : boss.type === 'REAPER_UFO'
            ? 2.2
            : boss.type === 'WHALE_KING'
            ? 2.8
            : 2.2;
        if (isEnraged) shootInterval *= 0.8;
        if (boss.shootTimer >= shootInterval) {
          boss.shootTimer = 0;
          this.fireBossAttack(boss, player);
        }
      }

      // Check Dive or Tractor Beam trigger
      const diveInterval = boss.type === 'REAPER_UFO' ? 11.0 : 8.0;
      if (boss.stateTimer >= diveInterval && !boss.laser?.active) {
        boss.stateTimer = 0;
        if (boss.type === 'REAPER_UFO') {
          boss.state = 'TRACTOR_BEAM';
          boss.tractorBeamActive = true;
          boss.tractorTimer = 3.5;
          this.onPlaySound?.('boost');
        } else {
          boss.state = 'PREPARE_DIVE';
          this.onPlaySound?.('die');
        }
      }
    } else if (boss.state === 'PREPARE_DIVE') {
      boss.hitFlashTimer = 600;
      if (boss.stateTimer >= 0.6) {
        boss.state = 'DIVING';
        boss.stateTimer = 0;
        boss.diveProgress = 0;
        boss.diveStartX = boss.x;
        boss.diveStartY = boss.y;
        boss.diveTargetX = player.x + (Math.random() - 0.5) * 40;
        boss.diveTargetY = this.arenaHeight + 50;
        boss.diveControlX =
          (boss.diveStartX + boss.diveTargetX) / 2 +
          (boss.x > this.arenaWidth / 2 ? -90 : 90);
        boss.diveControlY = player.y;
      }
    } else if (boss.state === 'DIVING') {
      boss.diveProgress += dtSec / 1.1;
      const t = Math.min(1.0, boss.diveProgress);
      const omt = 1 - t;
      boss.x =
        omt * omt * boss.diveStartX +
        2 * omt * t * boss.diveControlX +
        t * t * boss.diveTargetX;
      boss.y =
        omt * omt * boss.diveStartY +
        2 * omt * t * boss.diveControlY +
        t * t * boss.diveTargetY;

      const pSize = player.size ?? 18;
      const dist = Math.hypot(player.x - boss.x, player.y - boss.y);
      if (dist < pSize + boss.size && invulnerableTimer <= 0) {
        const raw = boss.stage >= 3 ? 42 : 28;
        this.onPlayerDamage?.(raw);
        if (boss.type === 'WHALE_KING') {
          this.applyBossLifesteal(boss, 120, player);
        }
      }

      if (boss.diveProgress >= 1.0) {
        boss.state = 'RETURNING';
        boss.stateTimer = 0;
        boss.x = Math.random() < 0.5 ? -30 : this.arenaWidth + 30;
        boss.y = -30;
      }
    } else if (boss.state === 'RETURNING') {
      const targetX = this.arenaWidth / 2;
      const targetY = boss.hoverBaseY;
      boss.x += (targetX - boss.x) * (dtSec * 3);
      boss.y += (targetY - boss.y) * (dtSec * 3);
      if (Math.hypot(targetX - boss.x, targetY - boss.y) < 15) {
        boss.state = 'FORMATION_HOVER';
        boss.stateTimer = 0;
      }
    } else if (boss.state === 'TRACTOR_BEAM') {
      boss.tractorTimer -= dtSec;
      boss.x += (this.arenaWidth / 2 - boss.x) * (dtSec * 2);
      boss.y += (boss.hoverBaseY - boss.y) * (dtSec * 2);

      if (boss.tractorTimer <= 0) {
        boss.tractorBeamActive = false;
        boss.state = 'FORMATION_HOVER';
        boss.stateTimer = 0;
      }
    }

    this.updateBossVisualEffects(dt);
  }

  public updateBossVisualEffects(dt: number): void {
    const dtSec = dt / 1000;

    // Siphon Orbs update with smooth Bezier arc
    const boss = this.currentBoss;
    for (let i = this.siphonOrbs.length - 1; i >= 0; i--) {
      const orb = this.siphonOrbs[i];
      orb.progress += dtSec * 2.2;
      if (boss) {
        orb.targetX = boss.x;
        orb.targetY = boss.y;
      }
      const t = Math.min(1.0, orb.progress);
      const midX = (orb.startX + orb.targetX) / 2 + Math.sin(t * Math.PI) * 40;
      const midY = (orb.startY + orb.targetY) / 2 - 20;
      const omt = 1 - t;
      orb.x = omt * omt * orb.startX + 2 * omt * t * midX + t * t * orb.targetX;
      orb.y = omt * omt * orb.startY + 2 * omt * t * midY + t * t * orb.targetY;

      if (orb.progress >= 1.0) {
        this.siphonOrbs.splice(i, 1);
      }
    }

    // Boss Floating Texts update
    for (let i = this.bossFloatingTexts.length - 1; i >= 0; i--) {
      const ft = this.bossFloatingTexts[i];
      ft.life -= dt;
      ft.y += ft.vy * dtSec;
      if (ft.life <= 0) {
        this.bossFloatingTexts.splice(i, 1);
      }
    }
  }

  public updateBullets(
    dt: number,
    player: { x: number; y: number; size: number },
    onHitPlayer?: (b: BossBullet) => void
  ): void {
    const dtSec = dt / 1000;
    for (let i = this.bossBullets.length - 1; i >= 0; i--) {
      const b = this.bossBullets[i];
      b.life -= dt;
      b.x += b.vx * dtSec * 60;
      b.y += b.vy * dtSec * 60;
      if (b.angle !== undefined && b.rotationSpeed !== undefined) {
        b.angle += b.rotationSpeed * dtSec;
      }

      // Out of bounds or dead
      if (
        b.life <= 0 ||
        b.x < -60 ||
        b.x > this.arenaWidth + 60 ||
        b.y < -60 ||
        b.y > this.arenaHeight + 60
      ) {
        this.bossBullets.splice(i, 1);
        continue;
      }

      // Player collision check
      const dist = Math.hypot(player.x - b.x, player.y - b.y);
      if (dist < player.size + b.radius) {
        this.bossBullets.splice(i, 1);
        onHitPlayer?.(b);
      }
    }
  }

  public clear(): void {
    this.currentBoss = null;
    this.bossBullets = [];
    this.siphonOrbs = [];
    this.bossFloatingTexts = [];
  }
}
