import { Icons } from '../../ui/icons.ts';
import { MoonRunEngine } from './MoonRunEngine.ts';

export class MoonRunView {
  private container: HTMLElement;
  private engine: MoonRunEngine | null = null;
  private cleanups: (() => void)[] = [];

  constructor(container: HTMLElement) {
    this.container = container;
  }

  public mount(): () => void {
    this.container.innerHTML = `
      <div class="game-view moonrun-view">
        <!-- Top HUD -->
        <header class="arcade-header">
          <div class="brand-section">
            <button id="btn-back-lobby" class="icon-btn back-btn" title="返回大廳" aria-label="返回大廳">
              ${Icons.back}
            </button>
            <span class="brand-title">MOON RUN</span>
          </div>

          <div class="hud-stats">
            <div class="stat-item">
              <span class="stat-label">ALTITUDE</span>
              <span id="stat-alt" class="stat-value score">0 M</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">HIGH</span>
              <span id="stat-high-alt" class="stat-value high-score">0 M</span>
            </div>
          </div>

          <div class="hud-actions">
            <button id="btn-audio" class="icon-btn" title="切換音效" aria-label="切換音效">
              ${Icons.volume}
            </button>
          </div>
        </header>

        <!-- Canvas Arena Container -->
        <main class="canvas-container">
          <div class="canvas-wrapper moonrun-wrapper">
            <canvas id="moonrun-canvas"></canvas>

            <!-- Game Over Modal -->
            <div id="gameover-modal" class="modal-overlay">
              <div class="game-modal">
                <h2 class="modal-title">CRASH LANDED</h2>
                <div class="modal-stats-grid">
                  <div class="modal-stat-box" style="grid-column: span 2;">
                    <span class="modal-stat-label">最高攀升高度</span>
                    <span id="modal-alt" class="modal-stat-val primary">0 M</span>
                  </div>
                </div>

                <div class="modal-actions">
                  <button id="btn-restart" class="btn-primary">
                    ${Icons.restart}
                    <span>LAUNCH AGAIN</span>
                  </button>
                  <div class="share-row">
                    <button id="btn-share-x" class="btn-secondary">
                      ${Icons.xLogo}
                      <span>SHARE TO X</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </main>

        <!-- Left / Right Touch Control Zone -->
        <nav class="moonrun-touch-deck" aria-label="Steering Controls">
          <button id="ctrl-left" class="moonrun-steer-btn" aria-label="向左移動">
            ${Icons.chevronLeft}
            <span>LEFT</span>
          </button>
          <button id="ctrl-right" class="moonrun-steer-btn" aria-label="向右移動">
            <span>RIGHT</span>
            ${Icons.chevronRight}
          </button>
        </nav>

        <!-- Desktop-only instructions bar -->
        <footer class="desktop-instructions">
          <span><span class="key-badge">A / D</span> 或 <span class="key-badge">← / →</span> 左右轉向</span>
          <span><span class="key-badge">R</span> 重新發射</span>
        </footer>
      </div>
    `;

    // Elements
    const canvas = this.container.querySelector('#moonrun-canvas') as HTMLCanvasElement;
    const canvasWrapper = this.container.querySelector('.canvas-wrapper') as HTMLElement;
    const btnBack = this.container.querySelector('#btn-back-lobby') as HTMLButtonElement;
    const statAlt = this.container.querySelector('#stat-alt') as HTMLElement;
    const statHighAlt = this.container.querySelector('#stat-high-alt') as HTMLElement;
    const btnAudio = this.container.querySelector('#btn-audio') as HTMLButtonElement;

    const gameoverModal = this.container.querySelector('#gameover-modal') as HTMLElement;
    const modalAlt = this.container.querySelector('#modal-alt') as HTMLElement;
    const btnRestart = this.container.querySelector('#btn-restart') as HTMLButtonElement;
    const btnShareX = this.container.querySelector('#btn-share-x') as HTMLButtonElement;

    const ctrlLeft = this.container.querySelector('#ctrl-left') as HTMLButtonElement;
    const ctrlRight = this.container.querySelector('#ctrl-right') as HTMLButtonElement;

    // Back to Lobby
    btnBack.addEventListener('click', () => {
      window.location.hash = '#/';
    });

    let currentAltitude = 0;

    // Initialize Engine
    this.engine = new MoonRunEngine(canvas, {
      onAltitudeChange: (altitude, highAlt) => {
        currentAltitude = altitude;
        statAlt.textContent = `${altitude.toLocaleString()} M`;
        statHighAlt.textContent = `${highAlt.toLocaleString()} M`;
      },
      onGameOver: (altitude) => {
        currentAltitude = altitude;
        modalAlt.textContent = `${altitude.toLocaleString()} M`;
        gameoverModal.classList.add('active');
      },
    });

    const engine = this.engine;

    // Audio Toggle
    btnAudio.addEventListener('click', () => {
      engine.soundManager.toggleMute();
      btnAudio.innerHTML = engine.soundManager.isMuted() ? Icons.volumeMute : Icons.volume;
    });

    // Replay
    btnRestart.addEventListener('click', () => {
      gameoverModal.classList.remove('active');
      engine.start();
    });

    // Share to X
    btnShareX.addEventListener('click', () => {
      const text = `我在 SNEK Moon Run 衝向月球，最高攀升 ${currentAltitude.toLocaleString()} 公尺！你能飛得比我更高嗎？\n\n#SNEK #MoonRun #Cardano #ToTheMoon $SNEK`;
      const url = 'https://www.snek.com.tw/game/#/game/moonrun';
      const tweetUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`;
      window.open(tweetUrl, '_blank', 'noopener,noreferrer');
    });

    // Left / Right Touch Handlers
    const bindSteer = (btn: HTMLElement, dir: -1 | 1) => {
      const start = (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        btn.classList.add('active');
        engine.setHorizontalMove(dir);
      };
      const stop = (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        btn.classList.remove('active');
        engine.setHorizontalMove(0);
      };

      btn.addEventListener('touchstart', start, { passive: false });
      btn.addEventListener('touchend', stop, { passive: false });
      btn.addEventListener('touchcancel', stop, { passive: false });
      btn.addEventListener('mousedown', start);
      btn.addEventListener('mouseup', stop);
      btn.addEventListener('mouseleave', stop);
    };

    bindSteer(ctrlLeft, -1);
    bindSteer(ctrlRight, 1);

    // Direct Canvas Touch Steering (Left half -> move left, Right half -> move right)
    let canvasTouchId: number | null = null;

    const handleCanvasTouch = (t: Touch) => {
      const rect = canvasWrapper.getBoundingClientRect();
      const relX = t.clientX - rect.left;
      if (relX < rect.width / 2) {
        engine.setHorizontalMove(-1);
        ctrlLeft.classList.add('active');
        ctrlRight.classList.remove('active');
      } else {
        engine.setHorizontalMove(1);
        ctrlRight.classList.add('active');
        ctrlLeft.classList.remove('active');
      }
    };

    canvasWrapper.addEventListener(
      'touchstart',
      (e: TouchEvent) => {
        if (gameoverModal.classList.contains('active')) return;
        if (e.touches.length > 0) {
          e.preventDefault();
          const t = e.touches[0];
          canvasTouchId = t.identifier;
          handleCanvasTouch(t);
        }
      },
      { passive: false }
    );

    canvasWrapper.addEventListener(
      'touchmove',
      (e: TouchEvent) => {
        if (canvasTouchId === null) return;
        for (let i = 0; i < e.touches.length; i++) {
          const t = e.touches[i];
          if (t.identifier === canvasTouchId) {
            e.preventDefault();
            handleCanvasTouch(t);
            break;
          }
        }
      },
      { passive: false }
    );

    const onCanvasTouchEnd = () => {
      canvasTouchId = null;
      engine.setHorizontalMove(0);
      ctrlLeft.classList.remove('active');
      ctrlRight.classList.remove('active');
    };

    canvasWrapper.addEventListener('touchend', onCanvasTouchEnd, { passive: true });
    canvasWrapper.addEventListener('touchcancel', onCanvasTouchEnd, { passive: true });

    // Keyboard controls
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'ArrowLeft' || e.code === 'KeyA') {
        engine.setHorizontalMove(-1);
      } else if (e.code === 'ArrowRight' || e.code === 'KeyD') {
        engine.setHorizontalMove(1);
      } else if (e.code === 'KeyR' && gameoverModal.classList.contains('active')) {
        gameoverModal.classList.remove('active');
        engine.start();
      }
    };
    const onKeyUp = (e: KeyboardEvent) => {
      if (['ArrowLeft', 'KeyA', 'ArrowRight', 'KeyD'].includes(e.code)) {
        engine.setHorizontalMove(0);
      }
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    this.cleanups.push(() => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    });

    // Start Engine
    engine.start();

    return () => {
      if (this.engine) {
        this.engine.destroy();
        this.engine = null;
      }
      this.cleanups.forEach((c) => c());
      this.cleanups = [];
      this.container.innerHTML = '';
    };
  }
}
