import { Enemy, EnemyType } from '../types.ts';
import { EnemyFactory } from '../factories/EnemyFactory.ts';

export interface WaveDirectorOptions {
  arenaWidth: number;
  arenaHeight: number;
  onSpawnEnemy: (enemy: Enemy) => void;
  maxEnemyCap?: number;
  baseSpawnInterval?: number;
}

export class WaveDirector {
  public arenaWidth: number;
  public arenaHeight: number;
  public spawnTimer: number = 0;
  public baseSpawnInterval: number = 850; // ms
  public maxEnemyCap: number;
  private onSpawnEnemy: (enemy: Enemy) => void;

  constructor(options: WaveDirectorOptions) {
    this.arenaWidth = options.arenaWidth;
    this.arenaHeight = options.arenaHeight;
    this.onSpawnEnemy = options.onSpawnEnemy;
    this.maxEnemyCap = options.maxEnemyCap ?? 75;
    if (options.baseSpawnInterval !== undefined) {
      this.baseSpawnInterval = options.baseSpawnInterval;
    }
  }

  public getBatchCount(stage: number, elapsedTime: number): number {
    if (elapsedTime > 120 || stage >= 3) {
      return Math.random() < 0.5 ? 3 : 2;
    } else if (elapsedTime > 60 || stage >= 2) {
      return Math.random() < 0.35 ? 2 : 1;
    }
    return 1;
  }

  public calculateSpawnInterval(stage: number, elapsedTime: number, spawnRateMult: number = 1.0): number {
    let interval = Math.max(260, this.baseSpawnInterval - elapsedTime * 14);
    if (spawnRateMult && spawnRateMult > 0) {
      interval /= spawnRateMult;
    }
    if (stage >= 4) {
      interval *= Math.max(0.65, 0.8 - (stage - 4) * 0.03);
    }
    return interval;
  }

  public update(
    dt: number,
    stage: number,
    elapsedTime: number,
    isBossActive: boolean,
    currentEnemyCount: number = 0,
    eventSpeedMult: number = 1.0,
    eventSpawnRateMult: number = 1.0
  ): void {
    if (isBossActive) return; // Do not spawn regular mob batches while boss is active

    this.spawnTimer += dt;
    const interval = this.calculateSpawnInterval(stage, elapsedTime, eventSpawnRateMult);

    if (this.spawnTimer >= interval) {
      this.spawnTimer = 0;

      if (currentEnemyCount < this.maxEnemyCap) {
        const batch = Math.min(
          this.getBatchCount(stage, elapsedTime),
          this.maxEnemyCap - currentEnemyCount
        );
        for (let b = 0; b < batch; b++) {
          this.triggerSpawn(stage, elapsedTime, false, eventSpeedMult, undefined, 1);
        }
      }
    }
  }

  public triggerSpawn(
    stage: number,
    elapsedTime: number = 0,
    forceEliteCheck: boolean = false,
    eventSpeedMult: number = 1.0,
    forceType?: EnemyType,
    customBatchCount?: number
  ): void {
    const batchCount = customBatchCount ?? this.getBatchCount(stage, elapsedTime);
    let eliteTriggered = false;

    for (let i = 0; i < batchCount; i++) {
      // Interleave High-Threat Elite Monster in stage 2+
      if (!forceType && stage >= 2 && !eliteTriggered && (forceEliteCheck || Math.random() < 0.08)) {
        const elite = EnemyFactory.createEliteEnemy(stage, this.arenaWidth, this.arenaHeight, undefined, eventSpeedMult);
        this.onSpawnEnemy(elite);
        eliteTriggered = true;
        continue;
      }

      const enemy = EnemyFactory.createEnemy(stage, this.arenaWidth, this.arenaHeight, forceType, eventSpeedMult);
      this.onSpawnEnemy(enemy);
    }
  }

  public spawnRetailMobWave(count: number, eventSpeedMult: number = 1.0): void {
    for (let i = 0; i < count; i++) {
      const mType: EnemyType = Math.random() < 0.65 ? 'RED_CANDLE' : 'FLASH_BEETLE';
      const enemy = EnemyFactory.createEnemy(3, this.arenaWidth, this.arenaHeight, mType, eventSpeedMult);
      this.onSpawnEnemy(enemy);
    }
  }
}
