import { Enemy, ExpGem } from '../types.ts';

export interface LootManagerOptions {
  onExpCollected: (amount: number, gem: ExpGem) => void;
  maxGemCap?: number;
}

export class LootManager {
  public gems: ExpGem[] = [];
  public maxGemCap: number;
  private onExpCollected: (amount: number, gem: ExpGem) => void;

  constructor(options: LootManagerOptions) {
    this.onExpCollected = options.onExpCollected;
    this.maxGemCap = options.maxGemCap ?? 160;
  }

  public addGem(x: number, y: number, value: number, tier: 'NORMAL' | 'ELITE' | 'BOSS' = 'NORMAL'): void {
    this.gems.push({
      id: `gem_${Date.now()}_${Math.random()}`,
      x,
      y,
      value,
      tier,
      angle: Math.random() * Math.PI * 2,
    });
  }

  public dropEnemyLoot(
    enemy: Enemy,
    elapsedTime: number = 0,
    eventExpDropMult: number = 1.0
  ): void {
    // Time scaling: capped at 1.5x hard ceiling to prevent runaway exponential EXP inflation
    const timeScale = Math.min(1.5, 1 + Math.floor(elapsedTime / 60) * 0.10);
    const dropMultiplier = (eventExpDropMult || 1) * timeScale;

    if (enemy.isElite) {
      // High-Threat Elite Monster drops guaranteed Elite Tier Gem (8 base EXP)
      const eliteVal = Math.max(5, Math.round(8 * dropMultiplier));
      this.addGem(enemy.x, enemy.y, eliteVal, 'ELITE');
    } else if (enemy.isBoss) {
      // Whale Boss drops a Mega Diamond Gem (65 base EXP) + 6 satellite gems
      const bossVal = Math.round(65 * dropMultiplier);
      this.addGem(enemy.x, enemy.y, bossVal, 'BOSS');
      for (let i = 0; i < 6; i++) {
        const offsetX = (Math.random() - 0.5) * 44;
        const offsetY = (Math.random() - 0.5) * 44;
        this.addGem(
          enemy.x + offsetX,
          enemy.y + offsetY,
          Math.max(1, Math.round(2 * dropMultiplier)),
          'NORMAL'
        );
      }
    } else if (enemy.type === 'BLACK_SWAN') {
      const swanVal = Math.max(4, Math.round(7 * dropMultiplier));
      this.addGem(enemy.x, enemy.y, swanVal, 'ELITE');
    } else if (enemy.type === 'LIQUIDATION_REAPER') {
      const reaperVal = Math.max(3, Math.round(5 * dropMultiplier));
      this.addGem(enemy.x, enemy.y, reaperVal, 'ELITE');
    } else if (enemy.type === 'FLASH_BEETLE') {
      const beetleVal = Math.max(1, Math.round(2 * dropMultiplier));
      this.addGem(enemy.x, enemy.y, beetleVal, 'NORMAL');
    } else if (enemy.type === 'BEAR') {
      const bearVal = Math.max(2, Math.round(3 * dropMultiplier));
      this.addGem(enemy.x, enemy.y, bearVal, 'ELITE');
    } else {
      // Normal Red Candle drops 1 base EXP
      const candleVal = Math.max(1, Math.round(1 * dropMultiplier));
      this.addGem(enemy.x, enemy.y, candleVal, 'NORMAL');
      if (Math.random() < 0.25) {
        this.addGem(
          enemy.x + (Math.random() - 0.5) * 14,
          enemy.y + (Math.random() - 0.5) * 14,
          candleVal,
          'NORMAL'
        );
      }
    }

    if (this.gems.length > 70) {
      this.compressGems(70);
    }
  }

  public compressGems(threshold: number = 70): void {
    if (this.gems.length <= threshold) return;

    while (this.gems.length > threshold) {
      let mergedVal = 0;
      let count = 0;
      let lastX = 0;
      let lastY = 0;

      for (let i = this.gems.length - 1; i >= 0 && count < 12; i--) {
        if (this.gems[i].tier === 'NORMAL') {
          mergedVal += this.gems[i].value;
          lastX = this.gems[i].x;
          lastY = this.gems[i].y;
          this.gems.splice(i, 1);
          count++;
        }
      }

      if (mergedVal > 0) {
        this.gems.push({
          id: `gem_merged_${Date.now()}_${Math.random()}`,
          x: lastX,
          y: lastY,
          value: mergedVal,
          tier: 'ELITE',
        });
      }

      if (count < 2) break; // No more normal gems to compress
    }
  }

  public update(
    _dt: number,
    player: { x: number; y: number; size: number; magnetRadius: number },
    magnetAll: boolean = false,
    feverMult: number = 1.0
  ): void {
    const effectiveMagnet = magnetAll ? 9999 : player.magnetRadius;
    const speed = magnetAll ? 12.5 : 7.5;

    for (let i = this.gems.length - 1; i >= 0; i--) {
      const g = this.gems[i];
      const dist = Math.hypot(player.x - g.x, player.y - g.y);
      g.angle = (g.angle || 0) + 0.05;

      if (dist < effectiveMagnet) {
        if (dist > 0) {
          g.x += ((player.x - g.x) / dist) * speed;
          g.y += ((player.y - g.y) / dist) * speed;
        }

        if (dist < player.size + 8) {
          const finalVal = Math.round(g.value * feverMult);
          const collectedGem = { ...g };
          this.gems.splice(i, 1);
          this.onExpCollected(finalVal, collectedGem);
        }
      }
    }
  }

  public clear(): void {
    this.gems = [];
  }
}
