import { Direction, Point, SnakeHeadState } from '../types.ts';

export class Snake {
  public segments: Point[] = [];
  public direction: Direction = 'RIGHT';
  private inputQueue: Direction[] = [];
  public growPending: number = 0;
  public state: SnakeHeadState = 'normal';
  private eatTimer: number = 0;

  // Head Sprite Cache
  private headImages: Record<SnakeHeadState, HTMLImageElement> = {
    normal: new Image(),
    eating: new Image(),
    boosting: new Image(),
    dead: new Image(),
  };

  private imagesLoaded: boolean = false;

  constructor(initialPosition: Point = { x: 10, y: 10 }, initialLength: number = 4) {
    this.reset(initialPosition, initialLength);
    this.loadSprites();
  }

  private loadSprites(): void {
    // Vite base is './', so relative paths resolve cleanly
    this.headImages.normal.src = './assets/face/SNEK_0000.webp';
    this.headImages.eating.src = './assets/face/SNEK_0002.webp';
    this.headImages.boosting.src = './assets/face/SNEK_0004.webp';
    this.headImages.dead.src = './assets/face/SNEK_0008.webp';

    let loadedCount = 0;
    const onLoad = () => {
      loadedCount++;
      if (loadedCount >= 4) {
        this.imagesLoaded = true;
      }
    };

    Object.values(this.headImages).forEach((img) => {
      img.onload = onLoad;
    });
  }

  public reset(pos: Point = { x: 10, y: 10 }, length: number = 4): void {
    this.segments = [];
    for (let i = 0; i < length; i++) {
      this.segments.push({ x: pos.x - i, y: pos.y });
    }
    this.direction = 'RIGHT';
    this.inputQueue = [];
    this.growPending = 0;
    this.state = 'normal';
    this.eatTimer = 0;
  }

  public get head(): Point {
    return this.segments[0];
  }

  public queueDirection(newDir: Direction): void {
    const lastQueued = this.inputQueue.length > 0 ? this.inputQueue[this.inputQueue.length - 1] : this.direction;
    if (this.isOpposite(lastQueued, newDir) || lastQueued === newDir) {
      return;
    }
    // Limit queue size to 2 to prevent stale key lag
    if (this.inputQueue.length < 2) {
      this.inputQueue.push(newDir);
    }
  }

  private isOpposite(dir1: Direction, dir2: Direction): boolean {
    return (
      (dir1 === 'UP' && dir2 === 'DOWN') ||
      (dir1 === 'DOWN' && dir2 === 'UP') ||
      (dir1 === 'LEFT' && dir2 === 'RIGHT') ||
      (dir1 === 'RIGHT' && dir2 === 'LEFT')
    );
  }

  public setEating(durationMs: number = 300): void {
    this.eatTimer = durationMs;
  }

  public update(dt: number, isBoosting: boolean): void {
    if (this.eatTimer > 0) {
      this.eatTimer -= dt;
      if (this.eatTimer <= 0) {
        this.eatTimer = 0;
      }
    }

    if (this.state !== 'dead') {
      if (this.eatTimer > 0) {
        this.state = 'eating';
      } else if (isBoosting) {
        this.state = 'boosting';
      } else {
        this.state = 'normal';
      }
    }
  }

  /**
   * 遊戲邏輯移動一步 (Tick)
   */
  public move(): Point {
    if (this.inputQueue.length > 0) {
      this.direction = this.inputQueue.shift()!;
    }

    const currentHead = this.head;
    const newHead: Point = { x: currentHead.x, y: currentHead.y };

    switch (this.direction) {
      case 'UP':
        newHead.y -= 1;
        break;
      case 'DOWN':
        newHead.y += 1;
        break;
      case 'LEFT':
        newHead.x -= 1;
        break;
      case 'RIGHT':
        newHead.x += 1;
        break;
    }

    this.segments.unshift(newHead);

    if (this.growPending > 0) {
      this.growPending--;
    } else {
      this.segments.pop();
    }

    return newHead;
  }

  public grow(amount: number = 1): void {
    this.growPending += amount;
  }

  public checkSelfCollision(): boolean {
    const head = this.head;
    for (let i = 1; i < this.segments.length; i++) {
      if (this.segments[i].x === head.x && this.segments[i].y === head.y) {
        return true;
      }
    }
    return false;
  }

  public getAngle(): number {
    switch (this.direction) {
      case 'RIGHT':
        return 0;
      case 'DOWN':
        return Math.PI / 2;
      case 'LEFT':
        return Math.PI;
      case 'UP':
        return -Math.PI / 2;
    }
  }

  /**
   * 繪製蛇身與蛇頭
   */
  public render(ctx: CanvasRenderingContext2D, cellSize: number, isBoosting: boolean): void {
    const total = this.segments.length;

    // 1. 繪製蛇身 (從尾巴到頸部)
    for (let i = total - 1; i >= 1; i--) {
      const seg = this.segments[i];
      const cx = seg.x * cellSize + cellSize / 2;
      const cy = seg.y * cellSize + cellSize / 2;

      // 漸層半徑大小 (尾部略微縮小，更有流暢度)
      const ratio = 1 - (i / total) * 0.35;
      const radius = (cellSize / 2 - 1.5) * ratio;

      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);

      if (isBoosting) {
        ctx.fillStyle = i % 2 === 0 ? '#ff9100' : '#00e676';
        ctx.shadowColor = '#ff5722';
        ctx.shadowBlur = 10;
      } else {
        // Snek 經典綠色階梯漸層
        const lightness = 45 + ((total - i) / total) * 15;
        ctx.fillStyle = `hsl(145, 100%, ${lightness}%)`;
        ctx.shadowColor = '#00e676';
        ctx.shadowBlur = 6;
      }

      ctx.fill();

      // 內部裝飾紋路 (微小亮斑)
      ctx.beginPath();
      ctx.arc(cx - radius * 0.25, cy - radius * 0.25, radius * 0.3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
      ctx.shadowBlur = 0;
      ctx.fill();

      ctx.restore();
    }

    // 2. 繪製蛇頭 (使用 SNEK 官方表情素材，並旋轉面向方向)
    const head = this.head;
    const hx = head.x * cellSize + cellSize / 2;
    const hy = head.y * cellSize + cellSize / 2;
    const angle = this.getAngle();

    ctx.save();
    ctx.translate(hx, hy);
    ctx.rotate(angle);

    const headImg = this.headImages[this.state];
    const headSize = cellSize * 1.5; // Slightly larger for charismatic meme face

    if (this.imagesLoaded && headImg && headImg.complete && headImg.naturalWidth > 0) {
      // 繪製頭部光暈
      if (this.state === 'boosting') {
        ctx.shadowColor = '#ff3d00';
        ctx.shadowBlur = 14;
      } else if (this.state === 'dead') {
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 14;
      } else {
        ctx.shadowColor = '#00e676';
        ctx.shadowBlur = 8;
      }

      ctx.drawImage(headImg, -headSize / 2, -headSize / 2, headSize, headSize);
    } else {
      // 備案：純 Canvas 幾何頭像 (若圖片尚未載入完成)
      ctx.beginPath();
      ctx.arc(0, 0, cellSize / 2, 0, Math.PI * 2);
      ctx.fillStyle = this.state === 'dead' ? '#ff1744' : '#00e676';
      ctx.fill();
    }

    ctx.restore();
  }
}
