import { IWeapon } from './IWeapon.ts';

export class VenomWeapon implements IWeapon {
  public readonly id = 'VENOM';
  public readonly name = '流動性買盤注入';

  public count: number = 1;
  public cooldown: number = 420;
  private timer: number = 0;

  public update(dt: number, engine: any): void {
    this.timer += dt;
    let effectiveCooldown = this.cooldown;
    if (engine.activeEvent?.effect.playerAttackSpeedMult) {
      effectiveCooldown /= engine.activeEvent.effect.playerAttackSpeedMult;
    }
    if (engine.isFever) {
      effectiveCooldown /= 2.0; // 2x fire rate in Fever!
    }

    if (this.timer >= effectiveCooldown && (engine.enemies.length > 0 || engine.currentBoss)) {
      this.timer = 0;
      this.fire(engine);
    }
  }

  public fire(engine: any): void {
    let closestTarget: { x: number; y: number } | null = null;
    let minDist = Infinity;

    if (engine.currentBoss) {
      closestTarget = engine.currentBoss;
      minDist = Math.hypot(engine.px - engine.currentBoss.x, engine.py - engine.currentBoss.y);
    }

    for (const e of engine.enemies) {
      const d = Math.hypot(engine.px - e.x, engine.py - e.y);
      if (d < minDist) {
        minDist = d;
        closestTarget = e;
      }
    }

    if (!closestTarget) return;
    const baseAngle = Math.atan2(closestTarget.y - engine.py, closestTarget.x - engine.px);
    const speed = 8.5;

    for (let i = 0; i < this.count; i++) {
      const spread = (i - (this.count - 1) / 2) * 0.22;
      const angle = baseAngle + spread;
      engine.projectiles.push({
        x: engine.px,
        y: engine.py,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        damage: 22,
        life: 2200,
      });
    }

    engine.soundManager.playBoost();
  }

  public upgrade(): void {
    if (this.count < 6) {
      this.count++;
    }
    this.cooldown = Math.max(180, this.cooldown - 30);
  }

  public reset(): void {
    this.count = 1;
    this.cooldown = 420;
    this.timer = 0;
  }
}
