import { Enemy, EnemyType } from '../types.ts';

export class EnemyFactory {
  public static createEnemy(
    stage: number,
    arenaWidth: number,
    arenaHeight: number,
    forceType?: EnemyType,
    eventSpeedMult: number = 1.0
  ): Enemy {
    let type: EnemyType = forceType || 'RED_CANDLE';
    if (!forceType) {
      const rand = Math.random();
      if (stage === 1) {
        type = rand < 0.65 ? 'RED_CANDLE' : 'BEAR';
      } else if (stage === 2) {
        if (rand < 0.35) type = 'RED_CANDLE';
        else if (rand < 0.60) type = 'BEAR';
        else if (rand < 0.82) type = 'LIQUIDATION_REAPER';
        else type = 'FLASH_BEETLE';
      } else if (stage === 3) {
        if (rand < 0.20) type = 'RED_CANDLE';
        else if (rand < 0.42) type = 'BEAR';
        else if (rand < 0.65) type = 'LIQUIDATION_REAPER';
        else if (rand < 0.82) type = 'FLASH_BEETLE';
        else type = 'BLACK_SWAN';
      } else {
        // Stage 4+
        if (rand < 0.18) type = 'RED_CANDLE';
        else if (rand < 0.38) type = 'BEAR';
        else if (rand < 0.60) type = 'LIQUIDATION_REAPER';
        else if (rand < 0.80) type = 'FLASH_BEETLE';
        else type = 'BLACK_SWAN';
      }
    }

    let hp = 30;
    let speed = 0.95;
    let size = 15;
    let color = '#d50000';

    if (type === 'RED_CANDLE') {
      hp = 18;
      speed = 1.45;
      size = 12;
      color = '#ff1744';
    } else if (type === 'LIQUIDATION_REAPER') {
      hp = 14;
      speed = 2.15;
      size = 13;
      color = '#e040fb';
    } else if (type === 'FLASH_BEETLE') {
      hp = 12;
      speed = 2.65;
      size = 12;
      color = '#c6ff00';
    } else if (type === 'BLACK_SWAN') {
      hp = 55;
      speed = 1.15;
      size = 17;
      color = '#7c4dff';
    } else {
      type = 'BEAR';
      hp = 36;
      speed = 0.90;
      size = 16;
      color = '#d50000';
    }

    if (stage >= 4) {
      const cycleBonus = 1 + (stage - 4) * 0.12;
      speed = Math.min(3.4, speed * (1.12 + (stage - 4) * 0.025));
      hp = Math.round(hp * 1.25 * cycleBonus);
    }

    speed *= eventSpeedMult;

    // Spawn at outer edge
    let x = 0;
    let y = 0;
    const edge = Math.floor(Math.random() * 4);
    if (edge === 0) {
      x = Math.random() * arenaWidth;
      y = -size * 2;
    } else if (edge === 1) {
      x = arenaWidth + size * 2;
      y = Math.random() * arenaHeight;
    } else if (edge === 2) {
      x = Math.random() * arenaWidth;
      y = arenaHeight + size * 2;
    } else {
      x = -size * 2;
      y = Math.random() * arenaHeight;
    }

    return {
      id: `enemy_${Date.now()}_${Math.random()}`,
      x,
      y,
      hp,
      maxHp: hp,
      speed,
      size,
      type,
      color,
      speedModifier: 1.0,
    };
  }

  public static createEliteEnemy(
    stage: number,
    arenaWidth: number,
    arenaHeight: number,
    forceType?: EnemyType,
    eventSpeedMult: number = 1.0
  ): Enemy {
    const baseEnemy = EnemyFactory.createEnemy(stage, arenaWidth, arenaHeight, forceType, eventSpeedMult);
    const eliteHp = Math.round(baseEnemy.hp * 4.5);

    return {
      ...baseEnemy,
      id: `elite_${baseEnemy.type}_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      hp: eliteHp,
      maxHp: eliteHp,
      size: Math.round(baseEnemy.size * 1.45),
      speed: baseEnemy.speed * 1.05,
      isElite: true,
      auraType: 'SPEED_AURA',
      auraRadius: 160,
      speedModifier: 1.0,
    };
  }
}
